/*
 * prog40_bisection_root.c
 *
 * Re‑implementation of the original program whose behaviour was observed
 * in the supplied binary.  The program reads a single integer argument,
 * validates it and then computes an approximation of its square‑root
 * using a simple bisection method (up to 60 iterations).  The output
 * format and error messages match exactly those produced by the original
 * binary.
 */

#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv)
{
    /* Input handling – the original program prints one of three messages
     * and exits without further output:
     *   NO_INPUT      – no command‑line argument supplied
     *   BAD_INPUT     – argument is not a valid integer or is negative
     *   OUT_OF_RANGE  – integer > 1 000 000
     */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    if (endptr == argv[1]) {          /* no conversion performed */
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 0) {                      /* negative numbers are rejected */
        puts("BAD_INPUT");
        return 0;
    }

    if (n > 1000000L) {               /* upper bound enforced by the binary */
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Bisection square‑root approximation.
     * The loop runs at most 60 times (0x3c) and after the loop the value
     * of `mid` is printed with the format "%.6f\n".
     */
    double low  = 0.0;
    double high = (double)n;   /* + 0.0 in the original binary */
    double mid  = 0.0;
    int   iter = 0;

    while (iter < 60) {
        mid = (high - low) * 0.5 + low;   /* midpoint */
        if ((double)n < mid * mid) {
            high = mid;                  /* n is smaller than mid² */
        } else {
            low = mid;                   /* n is larger or equal to mid² */
        }
        ++iter;
    }

    printf("%.6f\n", mid);
    return 0;
}
